import { useContext, useEffect, useState, useCallback } from 'react';
import { AuthContext } from '../../context/authContext';
import { DarkModeContext } from '../../context/darkModeContext';
import { useNavigate, useParams } from 'react-router-dom';
import axios from 'axios';
import './messages.scss';

const Messages = () => {
  const { currentUser } = useContext(AuthContext);
  const { darkMode } = useContext(DarkModeContext);
  const { userId } = useParams(); // Recipient ID from URL
  const navigate = useNavigate();
  const [friends, setFriends] = useState([]);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchFriends = useCallback(async () => {
    const token = localStorage.getItem('token');
    if (!token) {
      setError('Please log in to view friends.');
      return;
    }

    try {
      console.log(`Messages: Fetching friends for user ID: ${currentUser?._id}`);
      const res = await axios.get(`http://localhost:5000/api/users/${currentUser._id}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      console.log('Messages: Fetched friends=', JSON.stringify(res.data.friends, null, 2));
      setFriends(res.data.friends || []);
    } catch (err) {
      console.error('Messages: Error fetching friends:', err.message);
      console.error('Messages: Response:', err.response?.data);
      setError(err.response?.data?.message || 'Failed to load friends.');
    }
  }, [currentUser]);

  const fetchMessages = useCallback(async () => {
    if (!userId) return;

    const token = localStorage.getItem('token');
    try {
      console.log(`Messages: Fetching messages with user ID: ${userId}`);
      const res = await axios.get(`http://localhost:5000/api/messages/${userId}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      console.log('Messages: Fetched messages=', JSON.stringify(res.data, null, 2));
      setMessages(res.data);
      setError(null);
    } catch (err) {
      console.error('Messages: Error fetching messages:', err.message);
      console.error('Messages: Response:', err.response?.data);
      setError(err.response?.data?.message || 'Failed to load messages.');
    }
  }, [userId]);

  useEffect(() => {
    if (!currentUser) {
      console.log('Messages: No currentUser, redirecting to login');
      navigate('/login');
      return;
    }

    setLoading(true);
    Promise.all([fetchFriends(), fetchMessages()]).finally(() => setLoading(false));

    // Polling for message updates
    const interval = setInterval(() => {
      console.log('Messages: Polling for messages');
      fetchMessages();
    }, 5000); // Every 5 seconds

    return () => {
      console.log('Messages: Cleaning up polling interval');
      clearInterval(interval);
    };
  }, [currentUser, userId, navigate, fetchFriends, fetchMessages]);

  const handleSendMessage = async () => {
    if (!newMessage.trim() || !userId) return;

    const token = localStorage.getItem('token');
    try {
      console.log(`Messages: Sending message to user ID: ${userId}`);
      const res = await axios.post(
        'http://localhost:5000/api/messages',
        { recipientId: userId, content: newMessage },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      console.log('Messages: Message sent=', JSON.stringify(res.data, null, 2));
      setMessages([...messages, res.data.data]);
      setNewMessage('');
    } catch (err) {
      console.error('Messages: Error sending message:', err.message);
      console.error('Messages: Response:', err.response?.data);
      setError(err.response?.data?.message || 'Failed to send message.');
    }
  };

  const getProfilePictureUrl = (profilePicture) => {
    if (!profilePicture) {
      console.log('Messages: No profile picture provided, using default');
      return '/default-avatar.png';
    }
    if (profilePicture.startsWith('http')) {
      console.log('Messages: Using external profile picture URL:', profilePicture);
      return profilePicture;
    }
    const normalizedPath = profilePicture.replace(/^\/Uploads\//i, '/Uploads/');
    const url = `http://localhost:5000${normalizedPath}?t=${new Date().getTime()}`;
    console.log('Messages: Profile picture URL:', url);
    return url;
  };

  if (!currentUser) {
    return <div className={`messages ${darkMode ? 'theme-dark' : 'theme-light'}`}>Please log in to view messages.</div>;
  }

  if (loading) {
    return <div className={`messages ${darkMode ? 'theme-dark' : 'theme-light'}`}>Loading...</div>;
  }

  if (error) {
    return <div className={`messages ${darkMode ? 'theme-dark' : 'theme-light'} error`}>{error}</div>;
  }

  console.log('Messages: Rendering with friends=', JSON.stringify(friends, null, 2));
  console.log('Messages: Rendering with currentUser=', JSON.stringify(currentUser, null, 2));

  return (
    <div className={`messages ${darkMode ? 'theme-dark' : 'theme-light'}`}>
      <div className="friends-sidebar">
        <h3>Friends</h3>
        {friends.length > 0 ? (
          friends.map((friend) => (
            <div
              key={friend._id}
              className={`friend-item ${friend._id === userId ? 'active' : ''}`}
              onClick={() => navigate(`/messages/${friend._id}`)}
            >
              <img
                src={getProfilePictureUrl(friend.profilePicture)}
                alt={`${friend.username}'s profile`}
                className="friend-picture"
              />
              <span>{friend.username}</span>
            </div>
          ))
        ) : (
          <p>No friends found.</p>
        )}
      </div>
      <div className="chat-area">
        {userId ? (
          <>
            <h2>Chat with {friends.find(f => f._id === userId)?.username || 'User'}</h2>
            <div className="messages-list">
              {messages.length > 0 ? (
                messages.map((msg) => (
                  <div
                    key={msg._id}
                    className={`message ${msg.senderId._id === currentUser._id ? 'sent' : 'received'}`}
                  >
                    <p>{msg.content}</p>
                    <span className="timestamp">
                      {new Date(msg.timestamp).toLocaleString()}
                    </span>
                  </div>
                ))
              ) : (
                <p>No messages yet.</p>
              )}
            </div>
            <div className="message-input">
              <textarea
                value={newMessage}
                onChange={(e) => setNewMessage(e.target.value)}
                placeholder="Type a message..."
              />
              <button onClick={handleSendMessage}>Send</button>
            </div>
          </>
        ) : (
          <p>Select a friend to start chatting.</p>
        )}
      </div>
    </div>
  );
};

export default Messages;
